import markSmall from '@/assets/image/tono-mark-16.svg?url'
import markFull from '@/assets/image/tono-mark.svg?url'
import sunMark from '@/assets/image/tono-sun-mark.svg?url'

/**
 * The shared Tono product mark: the sun-on-the-horizon tile (owner-approved brand
 * sheet, 2026-10-12). Below 28px the pixel-aligned 16px drawing is used, as on the
 * taskbar. `variant="sun"` is the bare sun and reflections, for dark sea chrome.
 * The SVGs come from `src/dev/sea-shell/brand/`; the raster icons are generated by
 * `scripts/generate-tono-icons.py`.
 */

interface TonoLogoProps {
  connected: boolean
  /** Pixel size; the mark is square. */
  size?: number
  /** Sidebar/inline variant: smaller neutral shadow and no state animation. */
  compact?: boolean
  /** `tile` (default) is the app icon; `sun` drops the tile for dark chrome. */
  variant?: 'tile' | 'sun'
}

export const TonoLogo = ({ size = 52, variant = 'tile' }: TonoLogoProps) => {
  const src = variant === 'sun' ? sunMark : size < 28 ? markSmall : markFull
  return (
    <img
      src={src}
      alt=""
      aria-hidden
      draggable={false}
      width={size}
      height={size}
      style={{
        display: 'block',
        width: size,
        height: size,
        objectFit: 'contain',
      }}
    />
  )
}
